import axios from "axios";
import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";

export const useProductView = () => {
  const { name: productId } = useParams();
  const [product, setProduct] = useState({});
  const [selectedColor, setSelectedColor] = useState("");
  const [selectedSize, setSelectedSize] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState(1);

  const handleQuantityChange = ({ target: { value } }) => {
    setSelectedQuantity(value);
  };

  const getImage = (color) => {
    if (!product.image) return "";

    const image = product.image.find((image) =>
      image.name.includes(color)
    );
    return image ? image.url : "";
  };

  useEffect(() => {
    if (product.color && product.sizes) {
      setSelectedColor(product.color[0].name);
      setSelectedSize(product.sizes[0].name);
    }
  }, [product]);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const {
          data: { data },
        } = await axios.get(
          `http://localhost:1337/api/products/${productId-1}?populate=*`
        );
        console.log(data);
        setProduct(data);
      } catch (error) {
        console.log({ error });
      }
    };

    if (productId) {
      fetchProduct();
    }
  }, [productId]);

  return {
    product,
    getImage,
    selectedSize,
    selectedColor,
    selectedQuantity,
    setSelectedColor,
    setSelectedSize,
    handleQuantityChange,
  };
};
